/// <summary>
/// MPJ_24248 Pricing Data Extract
/// MarkupTable table extension
/// </summary>
[ExtensionOf(tableStr(MarkupAutoTable))]
final public class METMarkupAutoTableTable_Extension
{
   
}

Method.Source:
    /// <summary>
    /// COC on insert
    /// </summary>
    public void insert()
    {
        next insert();

        if(this.metIsGUPAutoCharge() && GUPParameters::find().METPriceChangeTrackingEnable)
        {
            MarkupAutoTable::metProcessTrackChange(this.RecId, SysAppCRUDOperation::Create, METFormEditAction::Save);
        }
    }

    /// <summary>
    /// COC on update
    /// </summary>
    public void update()
    {
        next update();

        if(this.metIsGUPAutoCharge())
        {
            MarkupAutoTable::metProcessTrackChange(this.RecId, SysAppCRUDOperation::Update, METFormEditAction::Save);
        }
    }

    /// <summary>
    /// CoC on delete
    /// </summary>
    public void delete()
    {
        if(this.metIsGUPAutoCharge())
        {
            MarkupAutoTable::metProcessTrackChange(this.RecId, SysAppCRUDOperation::Delete, METFormEditAction::Save);
        }

        next delete();
    }

/// <summary>
/// If a MarkupTable record is Edited from the Form capture the state for Change Tracking
/// </summary>
public void metEdit()
{
    if(this.metIsGUPAutoCharge() && GUPParameters::find().METPriceChangeTrackingEnable)
    {
        MarkupAutoTable::metProcessTrackChange(this.RecId, SysAppCRUDOperation::Update, METFormEditAction::Edit);
    }
}

    /// <summary>
    /// Process the change track
    /// </summary>
    /// <param name = "_refRecId">record id</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_editAction">Action type from the Form/Table</param>
    public static void metProcessTrackChange(RefRecid _refRecId, SysAppCRUDOperation _crud, METFormEditAction _editAction)
    {
        switch(_editAction)
        {
            case METFormEditAction::Edit :
                MarkupAutoTable::metTrackChangeDisabled(_refRecId, _crud, METPriceChangeType::AutoChargeDisabled);
                break;

            case METFormEditAction::Save :
                if(_crud == SysAppCRUDOperation::Delete)
                {
                    MarkupAutoTable::metTrackChangeDisabled(_refRecId, _crud, METPriceChangeType::AutoChargeDisabled);
                }
                else if (_crud == SysAppCRUDOperation::Update || _crud == SysAppCRUDOperation::Create)
                {
                    MarkupAutoTable::metTrackChangeEnabled(_refRecId, _crud, METPriceChangeType::AutoChargeEnabled);
                }
                break;
        }
    }

    /// <summary>
    /// Track the change for Enabled scenario
    /// </summary>
    /// <param name = "_refRecId">RecordId</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_priceChangeType">Price change type</param>
    public static void metTrackChangeEnabled(RefRecId _refRecId, SysAppCRUDOperation _crud, METPriceChangeType _priceChangeType)
    {
        MarkupAutoTable  metMarkupAutoTableLoc;

        metMarkupAutoTableLoc = MarkupAutoTable::metFindByRecId(_refRecId);

        Global::runAsync(classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, processEvent),
                        [_priceChangeType, metMarkupAutoTableLoc, _crud],
                        System.Threading.CancellationToken::None,
                        classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, callBackResult));
        
    }

    /// <summary>
    /// Track the change. Run in real time instead of seperate thread. Force user to wait while we capture existing state before changes are made
    /// </summary>
    /// <param name = "_refRecId">Record id</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_priceChangeType">Price change type</param>
    public static void metTrackChangeDisabled(RefRecId _refRecId, SysAppCRUDOperation _crud, METPriceChangeType _priceChangeType)
    {
        container       resultCon;
        MarkupAutoTable  metMarkupAutoTableLoc;

        metMarkupAutoTableLoc = MarkupAutoTable::metFindByRecId(_refRecId);

        resultCon = SysOperationSandbox::callStaticMethod(classNum(METPriceChangeEventManage),staticMethodStr(METPriceChangeEventManage,processEvent),
            [_priceChangeType, metMarkupAutoTableLoc, _crud], "@MET:WaitingPriceChangeTrackingProcess");

        METPriceChangeEventManage::buildResultMessage(resultCon);
    }

    /// <summary>
    /// Is this an Auto charge record
    /// </summary>
    /// <returns>True False</returns>
    public boolean metIsGUPAutoCharge()
    {
        boolean metRet = false;

        if( this.IsGupMarkupAuto == NoYes::Yes   &&
           (this.ModuleType      == MarkupModuleType::Cust || this.ModuleType == MarkupModuleType::Delivery) &&
            this.MarkupReturn    == ReturnCodeType::None)
        {
            metRet = true;
        }

        return metRet;
    }

    /// <summary>
    /// Find by RecId
    /// </summary>
    /// <param name = "_recId">Record id</param>
    /// <param name = "_forUpdate">Update</param>
    /// <returns>Table record</returns>
    public static MarkupAutoTable metFindByRecId(RecId _recId, boolean _forUpdate = false)
    {
        MarkupAutoTable metMarkupAutoTable;

        if(_recId)
        {
            metMarkupAutoTable.selectForUpdate(_forUpdate);

            select firstonly metMarkupAutoTable
                where metMarkupAutoTable.recId == _recId;
        }
        return metMarkupAutoTable;
    }
